INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q2404547', 'Siege of Jadotville', 'The Siege of Jadotville ([ʒa.do.vil]) was a major battle during the Congo Crisis, that began on 13 September 1961 and lasted for five days. A small contingent of the Irish Army''s 35th Battalion serving under the United Nations Operation in the Congo (ONUC), designated "A" Company, was besieged at the UN base near the mining town of Jadotville (modern-day Likasi) by Katangese forces loyal to the secessionist State of Katanga.', 1961, 9, 13, 1961, 9, 17, 'day', '13 September 1961 – 17 September 1961', 57, 'https://en.wikipedia.org/wiki/Siege_of_Jadotville'),
  ('Q2529018', 'assassination of Patrice Lumumba', 'Patrice Lumumba, inaugural Prime Minister of the Republic of the Congo, Léopoldville and leader of the Congolese National Movement (MNC), was assassinated on January 17, 1961 in Katanga, near Elizabethville, amidst the Congo Crisis that began in July 1960. Following the September 1960 coup led by Mobutu Sese Seko, Lumumba and his political retinue were detained by Mobutu''s forces in December 1960.', 1961, 1, NULL, NULL, NULL, NULL, 'month', 'January 1961', 39, 'https://en.wikipedia.org/wiki/Assassination_of_Patrice_Lumumba'),
  ('Q3718434', 'Kindu atrocity', 'The Kindu massacre, or Kindu atrocity, took place on 11 November 1961 in Kindu Port-Émpain, in the Congo-Léopoldville (the former Belgian Congo). Thirteen Italian airmen who were members of the United Nations Operation in the Congo who were sent to deal with the Congo Crisis were killed and partially eaten by locals.', 1961, 11, 12, NULL, NULL, NULL, 'day', '12 November 1961', 37, 'https://en.wikipedia.org/wiki/Kindu_atrocity'),
  ('Q85775188', 'Kwilu rebellion', 'The Kwilu rebellion (1963–1965) was a civil uprising which took place in the West of what is the modern-day Democratic Republic of the Congo. The rebellion took place in the wider context of the Cold War and the Congo Crisis.', 1963, 8, NULL, NULL, NULL, NULL, 'month', 'August 1963', 41, 'https://en.wikipedia.org/wiki/Kwilu_rebellion'),
  ('Q2656683', 'Simba Rebellion', 'The Simba rebellion, also known as the Orientale revolt, was a regional uprising which took place in the Democratic Republic of the Congo between 1963 and 1965 in the wider context of the Congo Crisis and the Cold War. The rebellion, located in the east of the country, was led by the followers of Patrice Lumumba, who had been ousted from power in 1960 by Joseph Kasa-Vubu and Joseph-Désiré Mobutu and subsequently killed in January 1961 in Katanga.', 1965, 11, NULL, NULL, NULL, NULL, 'month', 'November 1965', 55, 'https://en.wikipedia.org/wiki/Simba_rebellion'),
  ('Q125549056', 'Second Mobutu coup d''état', 'The second Mobutu coup d''état, launched on November 25, 1965, was a successful coup attempt in the Republic of the Congo (Léopoldville) by General Joseph Mobutu which overthrew President Joseph Kasa-Vubu and Prime Minister Evariste Kimba. The coup was caused by the political impasse between President Kasa-Vubu and Moïse Tshombe, which threatened to develop into a violent confrontation and destabilize the country even further.', 1965, 11, 25, NULL, NULL, NULL, 'day', '25 November 1965', 30, 'https://en.wikipedia.org/wiki/Second_Mobutu_coup_d''%C3%A9tat'),
  ('Q6416407', 'Stanleyville Mutinies', 'The Stanleyville mutinies, also known as the Mercenaries'' mutinies, occurred in the Democratic Republic of the Congo in 1966 and 1967.', 1966, NULL, NULL, 1967, NULL, NULL, 'year', '1966–1967', 26, 'https://en.wikipedia.org/wiki/Stanleyville_mutinies'),
  ('Q2745987', 'Battle of Kolwezi', 'The Battle of Kolwezi (French: Bataille de Kolwezi) was an airborne operation by French and Belgian airborne forces that took place in May 1978 in Zaire during the Shaba II invasion of Zaire by the Front for the National Liberation of the Congo (FLNC). It aimed at rescuing European and Zairean hostages held by FLNC rebels after they conquered the city of Kolwezi.', 1978, 5, 18, 1978, 5, 22, 'day', '18 May 1978 – 22 May 1978', 43, 'https://en.wikipedia.org/wiki/Battle_of_Kolwezi'),
  ('Q303801', 'Lord''s Resistance Army insurgency', 'The Lord''s Resistance Army insurgency is an ongoing conflict between the Lord''s Resistance Army (LRA), a Ugandan militant religious extremist group, against the government of Uganda. Following the Ugandan Civil War, militant Joseph Kony formed the Lord''s Resistance Army and launched an insurgency against the newly installed President Yoweri Museveni.', 1987, NULL, NULL, NULL, NULL, NULL, 'year', '1987', 52, 'https://en.wikipedia.org/wiki/Lord''s_Resistance_Army_insurgency'),
  ('Q75756', 'Second Congo War', 'The Second Congo War, also known as Africa''s World War or the Great War of Africa, was a major conflict that began on 2 August 1998 in the Democratic Republic of the Congo (DRC), just over a year after the First Congo War. The war initially erupted when Congolese president Laurent-Désiré Kabila turned against his former allies from Rwanda and Uganda, who had helped him seize power.', 1998, 8, 2, 2003, 6, 30, 'day', '2 August 1998 – 30 June 2003', 75, 'https://en.wikipedia.org/wiki/Second_Congo_War'),
  ('Q136301701', 'Genocost', 'Genocost, a portmanteau of genocide and cost, is a term used in the Democratic Republic of the Congo to describe the mass violence, displacement, sexual violence and other atrocities associated with decades of armed conflict and the exploitation of the country''s natural resources. The expression is commonly defined by its proponents as "genocide for economic gain" or "genocide for economic gains".', 1998, 8, 2, NULL, NULL, NULL, 'day', '2 August 1998', 39, 'https://en.wikipedia.org/wiki/Genocost'),
  ('Q133919', 'Ituri conflict', 'The Ituri conflict (French: Guerre d''Ituri) is an ongoing low intensity asymmetrical conflict between the agriculturalist Lendu and pastoralist Hema ethnic groups in the Ituri region of the north-eastern Democratic Republic of the Congo. While the two groups had fought since as early as 1972, the name "Ituri conflict" refers to the period of intense violence between 1999 and 2003.', 1999, NULL, NULL, 2003, NULL, NULL, 'year', '1999–2003', 53, 'https://en.wikipedia.org/wiki/Ituri_conflict'),
  ('Q3119043', 'Six-Day War', 'The Six-Day War (French: Guerre des Six Jours) was a series of armed confrontations between Ugandan and Rwandan forces around the city of Kisangani in the Democratic Republic of the Congo (DRC) from 5 to 10 June 2000, during the larger Second Congo War. While being allies, Uganda and Rwanda backed different rebel groups fighting against the government of the DRC. Kisangani was captured early on in the war and became a logistics base for both armies.', 2000, 6, 10, 2000, 6, 10, 'day', '10 June 2000', 45, 'https://en.wikipedia.org/wiki/Six-Day_War_(2000)'),
  ('Q39086159', 'Effacer le tableau', 'Effacer le tableau (French pronunciation: [efɑse lə tablo], lit. ''erase the board'' or ''clean the slate'') was a military operation carried out during the Second Congo War by the Movement for the Liberation of the Congo and Rally for Congolese Democracy-National between October 2002 and January 2003 against the government-aligned Rally for Congolese Democracy-Movement for Liberation. The goal of the operation was to capture the town of Mambasa, Ituri District, along with the areas to the south and southeast, ultimately aiming to seize the city of Beni in North Kivu.', 2002, 10, NULL, 2003, 1, NULL, 'month', 'October 2002 – January 2003', 39, 'https://en.wikipedia.org/wiki/Effacer_le_tableau'),
  ('Q108502717', 'Kisangani massacre', 'The Kisangani massacre occurred from May 13–15, 2002 in the city of Kisangani, Tshopo. After suppressing a mutiny, the Rally for Congolese Democracy started extrajudicial killings, lootings, and rape in the city, killing as many as 183 people.', 2002, 5, 13, 2002, 5, 15, 'day', '13 May 2002 – 15 May 2002', 34, 'https://en.wikipedia.org/wiki/Kisangani_massacre'),
  ('Q4937731', 'Bogoro massacre', 'The Bogoro massacre, which occurred on February 24, 2003, was an attack on the village of Bogoro in the Democratic Republic of the Congo (DRC) by the Nationalist and Integrationist Front (FNI) and the Front for Patriotic Resistance of Ituri (FRPI). The attackers allegedly went on an "indiscriminate killing spree", killing at least 200 civilians, imprisoning survivors in a room filled with corpses, and sexually enslaving women and girls.', 2003, 2, 24, NULL, NULL, NULL, 'day', '24 February 2003', 37, 'https://en.wikipedia.org/wiki/Bogoro_massacre'),
  ('Q327237', 'Kivu conflict', 'The Kivu conflict, is an umbrella term for a series of protracted armed conflicts in the North Kivu and South Kivu provinces in the eastern Democratic Republic of the Congo which began after the Second Congo War ended. Including neighboring Ituri province, there are more than 120 different armed groups active in the eastern Democratic Republic of Congo.', 2004, 6, 2, NULL, NULL, NULL, 'day', '2 June 2004', 63, 'https://en.wikipedia.org/wiki/Kivu_conflict'),
  ('Q770821', 'Hewa Bora Airways Flight 122', 'On 15 April 2008, Hewa Bora Airways Flight 122, a McDonnell Douglas DC-9-51 plane crashed into a residential and market area of Goma of the Democratic Republic of the Congo immediately south of Goma International Airport.', 2008, 4, 15, NULL, NULL, NULL, 'day', '15 April 2008', 47, 'https://en.wikipedia.org/wiki/Hewa_Bora_Airways_Flight_122'),
  ('Q1744007', '2008 Lake Kivu earthquake', 'The 2008 Lake Kivu earthquake shook several countries in Africa''s Great Lakes region at 07:34:12 (GMT) on 3 February. It measured 5.9 on the moment magnitude scale.', 2008, 2, 3, NULL, NULL, NULL, 'day', '3 February 2008', 48, 'https://en.wikipedia.org/wiki/2008_Lake_Kivu_earthquake'),
  ('Q4610765', '2008 Christmas massacres', 'The 2008 Christmas massacres were a series of attacks in several villages in Haut-Uele District, Democratic Republic of the Congo by the Lord''s Resistance Army (LRA) on 24–27 December 2008.', 2008, 12, 27, NULL, NULL, NULL, 'day', '27 December 2008', 41, 'https://en.wikipedia.org/wiki/2008_Christmas_massacres'),
  ('Q3050534', 'Makombo massacre', 'The Makombo massacre took place from 14 to 17 December 2009 in the Haut-Uele District of Democratic Republic of the Congo in the village and region of Makombo. Human Rights Watch (HRW) believes the attacks, which killed 321 people, were perpetrated by the Lord''s Resistance Army (LRA), which denied responsibility.', 2009, 12, 14, 2009, 12, 17, 'day', '14 December 2009 – 17 December 2009', 41, 'https://en.wikipedia.org/wiki/Makombo_massacre'),
  ('Q2290851', '2010 Filair Let L-410 crash', 'On 25 August 2010, a Let L-410 Turbolet passenger aircraft of Filair crashed on approach to Bandundu Airport in the Democratic Republic of the Congo, killing all but one of the 21 people on board. From a statement by the sole survivor, the accident was possibly the result of the occupants rushing to the front of the aircraft to escape from a crocodile smuggled on board by one of the passengers.', 2010, 8, 25, NULL, NULL, NULL, 'day', '25 August 2010', 55, 'https://en.wikipedia.org/wiki/2010_Filair_Let_L-410_crash'),
  ('Q1616631', 'Hewa Bora Airways Flight 952', 'On 8 July 2011, Hewa Bora Airways Flight 952, a Boeing 727 passenger jet on a domestic flight from Kinshasa, to Kisangani, Democratic Republic of the Congo (DRC), crashed on final approach at Kisangani, killing 77 of the 115 people on board.', 2011, 7, 8, NULL, NULL, NULL, 'day', '8 July 2011', 50, 'https://en.wikipedia.org/wiki/Hewa_Bora_Airways_Flight_952'),
  ('Q2976024', 'Georgian Airways Flight 834', 'On 4 April 2011, Georgian Airways Flight 834, a Bombardier CRJ100 passenger jet of Georgian Airways operating a domestic flight from Kisangani to Kinshasa in the Democratic Republic of the Congo (DRC), crashed while attempting to land at Kinshasa Airport. The aircraft, which was chartered by the United Nations, was trying to land during a thunderstorm.', 2011, 4, 4, NULL, NULL, NULL, 'day', '4 April 2011', 51, 'https://en.wikipedia.org/wiki/Georgian_Airways_Flight_834'),
  ('Q82962', 'M23 Rebellion', 'The First M23 rebellion was an armed conflict in North Kivu, Democratic Republic of the Congo, that occurred between the March 23 Movement (M23) rebel group and Congolese government forces between 4 April 2012 and 7 November 2013. It ended when a peace agreement was made among eleven African nations, and the M23 troops surrendered in Uganda.', 2012, 4, 4, 2013, 11, 7, 'day', '4 April 2012 – 7 November 2013', 50, 'https://en.wikipedia.org/wiki/M23_rebellion_(2012%E2%80%932013)'),
  ('Q17999999', '2014 Democratic Republic of the Congo Ebola virus outbreak', 'In 2014, an outbreak of Ebola virus disease in the Democratic Republic of the Congo (DRC) occurred. Genome sequencing has shown that this outbreak was not related to the 2014–15 West Africa Ebola virus epidemic, but was of the same EBOV species.', 2014, 11, NULL, 2014, 11, NULL, 'month', 'November 2014', 51, 'https://en.wikipedia.org/wiki/2014_Democratic_Republic_of_the_Congo_Ebola_outbreak'),
  ('Q28053348', 'December 2016 Congolese protests', 'On 20 December 2016 the Democratic Republic of the Congo''s president, Joseph Kabila, announced that he would not leave office despite the end of his constitutional term. Protests subsequently broke out across the country, which had never had a peaceful transfer of power since it gained independence in 1960.', 2016, 12, 20, NULL, NULL, NULL, 'day', '20 December 2016', 47, 'https://en.wikipedia.org/wiki/December_2016_Congolese_protests'),
  ('Q28792426', 'Kasaï-Central clashes (2016–present)', 'The Kamwina Nsapu rebellion, also spelled Kamuina Nsapu rebellion, was an uprising that took place in the Democratic Republic of the Congo between 2016 and 2019. It was instigated by the Kamwina Nsapu militia against state security forces in the provinces of Kasaï-Central, Kasaï, Kasaï-Oriental, Lomami and Sankuru.', 2016, 8, 8, NULL, NULL, NULL, 'day', '8 August 2016', 45, 'https://en.wikipedia.org/wiki/Kamwina_Nsapu_rebellion'),
  ('Q55887234', '2018–2020 Kivu Ebola epidemic', 'The Kivu Ebola epidemic was an outbreak of Ebola virus disease (EVD) mainly in eastern Democratic Republic of the Congo (DRC), and in other parts of Central Africa, from 2018 to 2020. Between 1 August 2018 and 25 June 2020 it resulted in 3,470 reported cases.', 2018, 8, 1, NULL, NULL, NULL, 'day', '1 August 2018', 58, 'https://en.wikipedia.org/wiki/Kivu_Ebola_epidemic'),
  ('Q105629905', 'Assassination of Luca Attanasio', 'Luca Attanasio, the Italian ambassador to the Democratic Republic of the Congo, was killed on 22 February 2021 along with two other people when a World Food Programme (WFP) delegation travelling on a field visit was attacked by armed individuals. The two-vehicle convoy with seven people was travelling in the Congolese province of North Kivu, from the province''s capital of Goma to a WFP school feeding programme in Rutshuru, a town 70 kilometres north of Goma, on a route that would have taken the vehicles through Virunga National Park.', 2021, 2, 22, NULL, NULL, NULL, 'day', '22 February 2021', 39, 'https://en.wikipedia.org/wiki/Murder_of_Luca_Attanasio'),
  ('Q106959869', '2021 Mont Nyiragongo eruption', 'On 22 May 2021, Mount Nyiragongo in the Democratic Republic of the Congo began erupting. As of 25 May, 32 people died as a result of the eruption and 1,000 homes were destroyed.', 2021, 5, 22, NULL, NULL, NULL, 'day', '22 May 2021', 43, 'https://en.wikipedia.org/wiki/2021_Mount_Nyiragongo_eruption'),
  ('Q110797392', 'Plaine Savo massacre', 'On 2 February 2022, over 60 civilians from the Hema ethnic group were killed in a massacre in Djugu territory, Ituri Province, Democratic Republic of the Congo. During the early hours, CODECO insurgents armed with machetes and edged weapons attacked Plaine Savo, a camp for internally displaced people in the northeast of the country in which around 4,000 people live.', 2022, 2, 2, NULL, NULL, NULL, 'day', '2 February 2022', 34, 'https://en.wikipedia.org/wiki/Plaine_Savo_massacre'),
  ('Q112535922', 'Democratic Republic of the Congo–Rwanda conflict', 'A conflict began between the Democratic Republic of the Congo (DRC) and Rwanda in 2022 after Rwandan forces intervened in the DRC to provide military support to the March 23 Movement (M23) rebel group, including fighting alongside them against the Congolese military (FARDC) and pro-government militias. A peace agreement between Rwanda and the DRC was signed on 27 June 2025, though fighting has continued and Rwandan troops remain in the DRC. Since the Second Congo War the eastern provinces of the DRC have been the site of an ongoing insurgency by various rebel groups, most notably the March…', 2022, 3, 27, NULL, NULL, NULL, 'day', '27 March 2022', 51, 'https://en.wikipedia.org/wiki/Democratic_Republic_of_the_Congo%E2%80%93Rwanda_conflict_(2022%E2%80%93present)'),
  ('Q112628065', 'M23 campaign', 'The M23 campaign is an ongoing series of military offensives launched by the March 23 Movement (M23), a Rwandan-backed rebel paramilitary group in the Democratic Republic of the Congo, since March 2022. In November 2021, M23 first launched attacks against the Congolese military (FARDC) and MONUSCO, seizing military positions in Ndiza, Cyanzu, and Runyoni in North Kivu Province.', 2022, 3, 27, NULL, NULL, NULL, 'day', '27 March 2022', 53, 'https://en.wikipedia.org/wiki/M23_campaign_(2022%E2%80%93present)'),
  ('Q115793067', 'Kishishe massacre', 'The Kishishe massacre (French: Massacre de Kishishe) took place on 21–30 November 2022 in the Bwito Chiefdom of Rutshuru Territory, North Kivu, in the eastern Democratic Republic of the Congo. The atrocity was perpetrated by the March 23 Movement (M23), a predominantly Rwandan-backed Tutsi armed group, following clashes with local militias and FARDC. A preliminary investigation by the United Nations reported that at least 171 civilians were summarily executed, while Congolese authorities initially estimated the death toll at around 300.', 2022, 11, 29, 2022, 12, 1, 'day', '29 November 2022 – 1 December 2022', 34, 'https://en.wikipedia.org/wiki/Kishishe_massacre'),
  ('Q116444885', 'Makugwe massacre', 'On 22 January 2023 in Makugwe in the Democratic Republic of the Congo, Islamists killed about 20 people.', 2023, 1, 22, NULL, NULL, NULL, 'day', '22 January 2023', 37, 'https://en.wikipedia.org/wiki/Makugwe_massacre'),
  ('Q118316106', '2023 Africa floods', 'From February to late-December 2023, floods killed over 2,600 people in 15 countries across Africa.', 2023, 2, 5, NULL, NULL, NULL, 'day', '5 February 2023', 43, 'https://en.wikipedia.org/wiki/2023_Africa_floods'),
  ('Q131920479', '2025 Goma offensive', 'The 2025 Goma offensive was a military operation launched by the March 23 Movement (M23), a Congolese rebel group that is part of the Congo River Alliance (AFC) and is supported by Rwanda, against the regional capital of Goma in the Democratic Republic of the Congo (DRC). It lasted from January 23 to January 30, 2025.', 2025, NULL, NULL, NULL, NULL, NULL, 'year', '2025', 45, 'https://en.wikipedia.org/wiki/2025_Goma_offensive'),
  ('Q135274035', '2025 Democratic Republic of the Congo–Rwanda peace agreement', 'The Democratic Republic of the Congo–Rwanda peace agreement, officially the Washington Accords for Peace and Prosperity, is a peace treaty intended to end the conflict between the Democratic Republic of the Congo (DRC) and Rwanda, signed on June 27, 2025, in Washington, D.C., United States. The main points of the agreement call for the withdrawal of Rwandan troops from the eastern DRC and for the Congolese government to end its support for the Democratic Forces for the Liberation of Rwanda (FDLR) militia.', 2025, 6, 27, NULL, NULL, NULL, 'day', '27 June 2025', 37, 'https://en.wikipedia.org/wiki/2025_DRC%E2%80%93Rwanda_peace_agreement');
